<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { Plus, RefreshCw, Save, Trash2 } from '@lucide/vue';import { api } from '../services/http';import SectionHeader from './SectionHeader.vue';import EmptyState from './EmptyState.vue'
const config=ref<any>({editable:{}});const instruments=ref<any>({instruments:[],limits:{}});const snapshot=ref<any>(null);const status=ref('');const failed=ref(false);const newInst=ref('');const closePassword=ref('')
const form=reactive<any>({okx_environment:'demo',okx_live_api_key:'',okx_live_secret_key:'',okx_live_passphrase:'',okx_demo_api_key:'',okx_demo_secret_key:'',okx_demo_passphrase:'',manual_close_enabled:false})
function note(t:string,e=false){status.value=t;failed.value=e;setTimeout(()=>status.value='',4500)}
async function load(){try{const [c,i]:any=await Promise.all([api('/api/v1/admin/config'),api('/api/v1/admin/instruments')]);config.value=c;instruments.value=i;Object.assign(form,{okx_environment:c.editable.okx_environment||'demo',manual_close_enabled:c.editable.manual_close_enabled})}catch(e:any){note(e.message,true)}}
async function save(){if(form.okx_environment==='live'&&prompt('输入 LIVE 确认切换到实盘环境')!=='LIVE')return;try{const p:any={okx_environment:form.okx_environment,manual_close_enabled:form.manual_close_enabled};for(const k of ['okx_live_api_key','okx_live_secret_key','okx_live_passphrase','okx_demo_api_key','okx_demo_secret_key','okx_demo_passphrase'])if(form[k])p[k]=form[k];await api('/api/v1/admin/config',{method:'PUT',body:JSON.stringify(p)});for(const k of Object.keys(form))if(k.includes('key')||k.includes('secret')||k.includes('passphrase'))form[k]='';note('OKX 环境、双凭证和安全开关已保存');await load()}catch(e:any){note(e.message,true)}}
async function add(){try{const d:any=await api('/api/v1/admin/instruments',{method:'POST',body:JSON.stringify({inst_id:newInst.value.toUpperCase()})});newInst.value='';note(`${d.added.instId} 已加入交易池`);await load()}catch(e:any){note(e.message,true)}}
async function remove(item:any){const phrase=`REMOVE ${item.instId}`;if(prompt(`输入确认短语：${phrase}`)!==phrase)return;try{await api(`/api/v1/admin/instruments/${item.instId}`,{method:'DELETE',body:JSON.stringify({confirmation:phrase})});note('标的已移除');await load()}catch(e:any){note(e.message,true)}}
async function positions(){try{snapshot.value=await api('/api/v1/admin/okx/account-snapshot')}catch(e:any){note(e.message,true)}}
async function closePosition(p:any){if(!form.manual_close_enabled)return note('请先启用并保存手动平仓开关',true);if(!closePassword.value)return note('请输入当前超级管理员密码',true);if(prompt(`输入确认短语：${p.close_confirmation}`)!==p.close_confirmation)return;try{const d:any=await api('/api/v1/admin/positions/close',{method:'POST',body:JSON.stringify({close_token:p.close_token,admin_password:closePassword.value,confirmation:p.close_confirmation})});closePassword.value='';note(`已确认平仓 ${d.instId} ${d.closed_size}`);await positions()}catch(e:any){note(e.message,true)}}
onMounted(load)
</script>
<template><div class="space-y-4"><div v-if="status" class="panel border-l-4 p-3 text-xs" :class="failed?'text-loss':'text-profit'">{{status}}</div><section class="panel p-4 sm:p-5"><SectionHeader title="OKX 双环境与交易安全" subtitle="DEMO/LIVE 凭证完全隔离"><template #actions><button class="btn btn-primary" @click="save"><Save :size="14"/>保存</button></template></SectionHeader><div class="grid gap-4 xl:grid-cols-2"><div class="subpanel p-4"><label class="label">当前环境</label><select v-model="form.okx_environment" class="input"><option value="demo">模拟盘 DEMO</option><option value="live">实盘 LIVE</option></select><label class="data-pill mt-3" :class="form.manual_close_enabled?'data-pill-warning':''"><input v-model="form.manual_close_enabled" type="checkbox"/>允许确认式手动平仓</label></div><div class="subpanel p-4"><b class="text-sm text-profit">DEMO 凭证</b><input v-model="form.okx_demo_api_key" class="input mt-3" type="password" placeholder="API Key（留空不改）"/><input v-model="form.okx_demo_secret_key" class="input mt-2" type="password" placeholder="Secret（留空不改）"/><input v-model="form.okx_demo_passphrase" class="input mt-2" type="password" placeholder="Passphrase（留空不改）"/></div><div class="subpanel p-4 xl:col-start-2"><b class="text-sm text-loss">LIVE 凭证</b><input v-model="form.okx_live_api_key" class="input mt-3" type="password" placeholder="API Key（留空不改）"/><input v-model="form.okx_live_secret_key" class="input mt-2" type="password" placeholder="Secret（留空不改）"/><input v-model="form.okx_live_passphrase" class="input mt-2" type="password" placeholder="Passphrase（留空不改）"/></div></div></section><section class="panel p-4 sm:p-5"><SectionHeader title="交易标的池" :subtitle="`最少 ${instruments.limits?.minimum||1}，最多 ${instruments.limits?.maximum||6}，BTC 必选`" :count="instruments.instruments?.length||0"/><div class="flex gap-2"><input v-model="newInst" class="input" placeholder="例如 ETH-USDT-SWAP"/><button class="btn btn-primary shrink-0" @click="add"><Plus :size="14"/>添加</button></div><div class="mt-4 grid gap-2.5 sm:grid-cols-2 xl:grid-cols-3"><article v-for="i in instruments.instruments||[]" :key="i.instId" class="subpanel p-4"><div class="flex justify-between"><div><b>{{i.name}}</b><p class="mt-1 text-[9px] font-mono muted">{{i.instId}}</p></div><span class="badge" :class="i.has_tracker?'badge-warning':'badge-profit'">{{i.has_tracker?'持仓追踪中':'可管理'}}</span></div><div class="mt-3 flex gap-2"><span class="data-pill">ctVal <b>{{i.ctVal}}</b></span><span class="data-pill">风险 <b>{{i.risk_per_trade_usd}}U</b></span></div><button v-if="!i.protected" class="btn btn-danger mt-3" :disabled="i.has_tracker" @click="remove(i)"><Trash2 :size="13"/>删除</button></article></div></section><section class="panel p-4 sm:p-5"><SectionHeader title="OKX 当前持仓与快速平仓" subtitle="每次刷新生成90秒一次性平仓令牌"><template #actions><button class="btn" @click="positions"><RefreshCw :size="14"/>读取账户</button></template></SectionHeader><label class="label">当前超级管理员密码（仅用于平仓二次认证）</label><input v-model="closePassword" class="input max-w-lg" type="password"/><div v-if="snapshot" class="mt-4"><div class="data-pill" :class="snapshot.environment==='live'?'data-pill-loss':'data-pill-profit'">{{snapshot.environment.toUpperCase()}} · 持仓 {{snapshot.positions.length}} · 挂单 {{snapshot.orders.length}}</div><div v-if="snapshot.positions.length" class="mt-3 grid gap-2.5 lg:grid-cols-2"><article v-for="p in snapshot.positions" class="subpanel p-4"><div class="flex justify-between"><b>{{p.instId}}</b><span class="badge" :class="p.posSide==='long'?'badge-profit':'badge-loss'">{{p.posSide}}</span></div><div class="mt-3 grid grid-cols-3 gap-2 text-xs"><span class="data-pill">数量 <b>{{p.pos}}</b></span><span class="data-pill">模式 <b>{{p.mgnMode}}</b></span><span class="data-pill" :class="Number(p.upl)>=0?'data-pill-profit':'data-pill-loss'">浮盈 <b>{{Number(p.upl||0).toFixed(4)}}</b></span></div><button class="btn btn-danger mt-3" @click="closePosition(p)">确认快速平仓</button></article></div><EmptyState v-else text="当前环境无持仓"/></div></section></div></template>
